{
  "title": "The Glass Diver and the Ruined City",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "The massive iron gates of the ruined city stand half-open, rusted and hung with tattered royal banners. The glass diver stands before them, his diving helmet reflecting the shattered skyline.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer reads her map at the gate.",
      "visual_description": "Mara the Cartographer kneels on the cobblestones, unrolling a stained parchment map. Her brass compass glints in the pale light as she traces a route through the city.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp warns of the cursed tower ahead.",
      "visual_description": "The Oracle Lamp sits on a broken wall, its single flame-eye flickering. The glass diver and Mara listen as the lamp speaks, its light casting long shadows across the rubble.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Sleeping Tax Collector blocks the main road.",
      "visual_description": "The Sleeping Tax Collector lies slumped against a pile of ledgers, his head resting on a stamp-paper pillow. He snores softly, oblivious to the rescue party approaching.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead to scout.",
      "visual_description": "The Tin Fox dashes across a cracked plaza, its key-wind tail spinning. It pauses to sniff at a fallen royal banner before disappearing into an alley.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The party passes under a crumbling archway.",
      "visual_description": "A stone archway covered in faded murals looms overhead. The glass diver, Mara, and the Oracle Lamp walk beneath it, their footsteps echoing in the silence.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The Tin Fox reports a trapped square.",
      "visual_description": "The Tin Fox returns to the group, its blue glass eyes glowing. It gestures with its snout toward a square filled with shattered glass and hidden tripwires.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The Sleeping Tax Collector stirs and mutters a clue.",
      "visual_description": "The Sleeping Tax Collector shifts in his sleep, mumbling about a 'key in the bell tower.' A stamped paper falls from his sleeve and flutters to the ground.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through a mirror into the bell tower.",
      "visual_description": "The glass diver approaches a tall mirror leaning against a wall. He presses his hand to the glass and steps through, rippling like water, emerging inside a dusty bell tower.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Mara locates the hidden key in the bell tower.",
      "visual_description": "Inside the bell tower, Mara runs her ink-stained fingers along a beam and finds a brass key wedged in a crack. The Oracle Lamp casts a steady glow on her work.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The key opens a magic door behind a waterfall.",
      "visual_description": "The party stands before a cascading waterfall that hides a glowing door. The glass diver inserts the key, and the water parts to reveal an ornate entrance.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Sleeping Tax Collector wanders into the throne room.",
      "visual_description": "The Sleeping Tax Collector sleepwalks through the magic door, still clutching his ledger. He shuffles across a vast throne room, oblivious to the danger.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Armored patrols march through the corridors.",
      "visual_description": "A squad of empty suits of armor clanks down a corridor, their visors glowing with blue light. The party hides behind a pillar as they pass.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The Oracle Lamp warns of a collapsing ceiling.",
      "visual_description": "The Oracle Lamp's eye-flame flares red as it warns of a trap. Cracks spider across the ceiling above, and dust rains down on the party.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The Tin Fox disables the pressure plates.",
      "visual_description": "The Tin Fox scurries ahead, pressing its small paws on hidden pressure plates to deactivate them. Its key-wind tail spins rapidly as it works.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The party reaches the bridge under moonlight.",
      "visual_description": "The group emerges onto a stone bridge spanning a dark chasm. Moonlight glints off the glass diver's helmet as they hurry across, the ruined city behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to crumble behind them.",
      "visual_description": "Stones fall from the bridge into the abyss as the party runs. The glass diver turns to see the city's towers collapsing in the distance.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes into the free lands beyond.",
      "visual_description": "The party stands on solid ground, looking back at the ruined city across the broken bridge. The Oracle Lamp's flame dims to a calm glow, and the Tin Fox sits at Mara's feet.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

